-- Solo lectura, proyecto DEV del equipo seleccionado explícitamente.
SELECT version,nombre,hu,aplicada_en,aplicada_por FROM public.treksafe_migraciones WHERE version IN ('015','020','021','022','023','024','025','026','027','028') ORDER BY version;
SELECT x.nombre,to_regclass('public.'||x.nombre) AS objeto,c.relrowsecurity AS rls FROM (VALUES ('creaciones_plan_offline'),('informes_cierre_incidente'),('intentos_outbox'),('retornos_confirmados'),('solicitudes_reintento_outbox')) x(nombre) LEFT JOIN pg_class c ON c.oid=to_regclass('public.'||x.nombre);
SELECT p.proname,pg_get_function_identity_arguments(p.oid) AS argumentos,p.prosecdef,p.proconfig,md5(replace(p.prosrc,chr(13),'')) AS cuerpo_lf_md5,has_function_privilege('anon',p.oid,'execute') AS anon_execute,has_function_privilege('authenticated',p.oid,'execute') AS authenticated_execute,has_function_privilege('service_role',p.oid,'execute') AS service_execute FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('treksafe_crear_plan_borrador','treksafe_cerrar_incidente','treksafe_marcar_incidente_localizado','treksafe_leer_ultimo_cierre_incidente','treksafe_pendientes_outbox','treksafe_reservar_outbox','treksafe_iniciar_intento_outbox','treksafe_finalizar_intento_outbox','treksafe_confirmar_retorno_con_outbox','treksafe_despachos_autorizados','treksafe_reintentar_despacho') ORDER BY p.proname;
SELECT has_column_privilege('service_role','public.incidentes','estado','UPDATE') AS puede_estado,has_column_privilege('service_role','public.incidentes','cerrado_en','UPDATE') AS puede_cerrado_en,has_column_privilege('service_role','public.incidentes','version','UPDATE') AS puede_version;
